from collections import Counter, defaultdict
def fill(g, bord=1, frame=4):
    h,w=len(g),len(g[0])
    dg=defaultdict(Counter)
    for i in range(3,h):
        for j in range(3,w):
            if g[i][j]!=0: dg[i+j][g[i][j]]+=1
    gval={}
    for k,c in dg.items():
        if len(c)>1: print('diag',k,'votes',dict(c))
        gval[k]=c.most_common(1)[0][0]
    # fill any missing diagonal periodically using smallest period of known vals
    mx=max(gval)
    out=[row[:] for row in g]
    for i in range(h):
        for j in range(w):
            if out[i][j]!=0: continue
            if i<=1 or j<=1: out[i][j]=bord
            elif i==2 or j==2: out[i][j]=frame
            else:
                k=i+j
                out[i][j]=gval.get(k) or next((gval[k-p] for p in range(1,mx+1) if k-p in gval), 0)
    return out
